import shutil, openpyxl

shutil.copy(INIT, OUT)
vals = openpyxl.load_workbook(INIT, data_only=True)
wb = openpyxl.load_workbook(OUT)

sheet = "Sheet1"
if sheet not in vals.sheetnames:
    ws_vals = vals.create_sheet(sheet)
else:
    ws_vals = vals[sheet]
if sheet not in wb.sheetnames:
    ws = wb.create_sheet(sheet)
else:
    ws = wb[sheet]

words = []
upper_to_orig = {}
for r in range(1, ws_vals.max_row + 1):
    v = ws_vals.cell(row=r, column=1).value
    if v is None:
        continue
    s = str(v).strip()
    if not s:
        continue
    words.append(s)
    u = s.upper()
    if u not in upper_to_orig:
        upper_to_orig[u] = s

upper_set = set(upper_to_orig.keys())
pairs = set()
for s in words:
    u = s.upper()
    if 'S' in u:
        for vowel in 'AEIOU':
            cand = u.replace('S', vowel)
            if cand in upper_set and cand != u:
                pairs.add((cand, u))

final = [(upper_to_orig[a], upper_to_orig[b]) for a, b in pairs]
final.sort(key=lambda p: (p[0].lower(), p[1].lower(), p[0], p[1]))

clear_to = max(65, len(final) + 1)
for r in range(1, clear_to + 1):
    ws.cell(row=r, column=7).value = None
    ws.cell(row=r, column=8).value = None

for i, (a, b) in enumerate(final, start=1):
    ws.cell(row=i, column=7).value = a
    ws.cell(row=i, column=8).value = b

wb.save(OUT)
print("words", len(words), "pairs", len(final))
print(final[:5])
